SELECT COUNT(s.CDSCode) AS Total_Schools
FROM schools s
WHERE s.County = 'Monterey';

SELECT CDSCode
FROM frpm
WHERE `Enrollment (K-12)` > 500;

SELECT COUNT(DISTINCT `CDSCode`) AS num_schools_with_high_enrollment
FROM frpm
WHERE `Enrollment (K-12)` > 500;

SELECT COUNT(event_id) 
FROM event 
WHERE type = 'Meeting';

SELECT event_name
FROM event
WHERE type = 'Meeting' AND status = 'Open';

SELECT first_name, last_name
FROM member
WHERE position = 'President';

SELECT first_name, last_name, email
FROM member
WHERE position = 'President';

SELECT event_name 
FROM event 
WHERE type = 'Social';

SELECT event_name 
FROM event 
WHERE type = 'Social' AND status = 'Closed';

SELECT COUNT(event_id) AS total_closed_social_events
FROM event
WHERE type = 'Social' AND status = 'Closed';

SELECT SUM(cost) AS total_cost
FROM expense
WHERE approved = 'true';

SELECT SUM(cost) 
FROM expense 
WHERE approved = 'true' AND cost > 50;

SELECT AVG(cost) AS average_cost
FROM expense
WHERE approved = 'true' AND cost > 50;

SELECT COUNT(*) 
FROM member 
WHERE t_shirt_size = 'Medium';

SELECT COUNT(*) 
FROM member 
WHERE t_shirt_size = 'Large';

SELECT first_name, last_name
FROM member
WHERE t_shirt_size = 'Large';

SELECT COUNT(*) 
FROM loan 
WHERE status = 'A';

SELECT COUNT(*) 
FROM loan 
WHERE duration > 24;

SELECT AVG(amount) AS average_loan_amount
FROM loan
WHERE duration > 24;

SELECT gender, COUNT(*) AS count
FROM client
GROUP BY gender;

SELECT COUNT(*) 
FROM trans 
WHERE type = 'PRIJEM';

SELECT COUNT(*)
FROM trans
WHERE type = 'PRIJEM' AND amount > 10000;

SELECT SUM(amount) AS total_amount
FROM trans
WHERE type = 'PRIJEM' AND amount > 10000;

SELECT COUNT(*) 
FROM loan 
WHERE status = 'B';

SELECT COUNT(*) 
FROM loan 
WHERE status = 'B' AND amount > 100000;

SELECT AVG(amount) AS average_loan_amount
FROM loan
WHERE status = 'B' AND amount > 100000;

SELECT COUNT(trans_id)
FROM trans
WHERE balance > 0;

SELECT COUNT(*) 
FROM trans 
WHERE type = 'VYDAJ' AND balance > 0;

SELECT COUNT(*) AS transaction_count
FROM trans
WHERE type = 'VYDAJ';

SELECT COUNT(DISTINCT driverId) AS total_drivers_with_wins
FROM results
WHERE position = 1;

SELECT COUNT(*) AS total_races
FROM races
WHERE year = 2010;

SELECT forename, surname
FROM drivers
WHERE nationality = 'British';

SELECT COUNT(*) AS British_Drivers
FROM drivers
WHERE nationality = 'British';

SELECT COUNT(*) AS german_driver_count
FROM drivers
WHERE nationality = 'German';

SELECT COUNT(DISTINCT circuitId) AS distinct_circuits
FROM races
WHERE year = 2010;

SELECT COUNT(DISTINCT circuitId) 
FROM races 
WHERE year = 2010 AND round BETWEEN 1 AND 10;

SELECT COUNT(*) 
FROM races 
WHERE year = 2009;

SELECT COUNT(*) 
FROM pitStops 
WHERE duration < '30';

SELECT COUNT(*) 
FROM constructors 
WHERE nationality = 'UK';

SELECT name
FROM constructors
WHERE nationality = 'UK';

SELECT name
FROM constructors
WHERE nationality = 'Italian';

SELECT COUNT(*) 
FROM cards 
WHERE borderColor = 'black';

SELECT COUNT(*) 
FROM cards 
WHERE borderColor = 'black' AND availability = 'mtgo';

SELECT COUNT(*) 
FROM cards 
WHERE borderColor = 'white' AND availability = 'mtgo';

SELECT name
FROM sets
WHERE block = 'Core Set' AND type = 'core';

SELECT name, releaseDate
FROM sets
WHERE block = 'Core Set' AND type = 'core';

SELECT COUNT(*)
FROM sets
WHERE block = 'Core Set' AND type = 'core';

SELECT COUNT(*) 
FROM cards 
WHERE colors LIKE '%R%';

SELECT COUNT(*) 
FROM cards 
WHERE colors LIKE '%red%' AND borderColor = 'black';

SELECT COUNT(*) 
FROM cards 
WHERE borderColor = 'black' AND colors = 'blue';

SELECT COUNT(*) 
FROM cards 
WHERE hasFoil = 1 AND hasNonFoil = 0;

SELECT COUNT(*)
FROM cards
WHERE hasFoil = 0;

SELECT COUNT(DISTINCT c.uuid) AS total_cards_with_ruling
FROM cards c
JOIN rulings r ON c.uuid = r.uuid;

SELECT COUNT(*)
FROM Patient
WHERE SEX = 'F';
